'use strict';

const fs = require('fs');
const path = require('path');

function decode(value) {
  return Buffer.from(value || '', 'hex').toString('utf8');
}

function emit(kind, ...values) {
  process.stdout.write([kind].concat(values.map(value => Buffer.from(String(value), 'utf8').toString('hex'))).join('\t') + '\n');
}

function installBabel(transformPath) {
  let presetEnv;
  try { presetEnv = require('@babel/preset-env'); } catch (_) {}
  const presets = [];
  if (presetEnv) presets.push([presetEnv.default || presetEnv, {targets: {node: true}}]);
  presets.push(/\.tsx?$/.test(transformPath) ? require('@babel/preset-typescript').default : require('@babel/preset-flow').default);
  require('@babel/register')({
    configFile: false,
    babelrc: false,
    presets,
    plugins: [
      require('@babel/plugin-transform-class-properties').default,
      require('@babel/plugin-transform-nullish-coalescing-operator').default,
      require('@babel/plugin-transform-optional-chaining').default,
      require('@babel/plugin-transform-modules-commonjs').default,
      require('@babel/plugin-transform-private-methods').default,
    ],
    extensions: [...require('@babel/core').DEFAULT_EXTENSIONS, '.ts', '.tsx'],
    ignore: [/@babel\/parser/, /\/flow-parser\//, /\/recast\//, /\/ast-types\//],
  });
}

async function main(requestPath) {
  const lines = fs.readFileSync(requestPath, 'utf8').split(/\r?\n/);
  const transformPath = decode(lines[0]);
  const filePath = decode(lines[1]);
  const source = decode(lines[2]);
  const options = JSON.parse(decode(lines[3]));
  if (options.babel !== false && options.babel !== 0 && !/^https?:/.test(transformPath)) installBabel(transformPath);
  const jscodeshift = require(path.resolve(__dirname, '..', 'src', 'core'));
  const loaded = require(transformPath);
  const transform = typeof loaded.default === 'function' ? loaded.default : loaded;
  const parserExport = loaded.parser;
  let parser = parserExport;
  if (typeof parser === 'string') parser = require(path.resolve(__dirname, '..', 'src', 'getParser'))(parser, options.parserConfig);
  const j = parser ? jscodeshift.withParser(parser) : jscodeshift.withParser(options.parser || 'babel');
  const reports = [];
  const stats = [];
  const api = {
    j,
    jscodeshift: j,
    stats: name => { if (options.dry) stats.push([name, 1]); },
    report: message => reports.push(message),
  };
  let result = await transform({path: filePath, source}, api, options);
  if (result !== undefined && result !== null && typeof result !== 'string') result = String(result);
  if (result === undefined || result === null) emit('RESULT', 'skip', '');
  else emit('RESULT', 'value', result);
  for (const [name, quantity] of stats) emit('STAT', name, quantity);
  for (const report of reports) emit('REPORT', report);
